    for block_r, block_c, seed in ((0, 1, 1), (1, 0, 2), (1, 1, 3)):
        shuffled = cells[:]
        random.Random(seed).shuffle(shuffled)
        for i in range(h):
            for j in range(w):
                out[block_r * h + i][block_c * w + j] = shuffled[i * w + j]
    return out
